  },
  "contributors": [
    "Tilman Potthof"
  ],
  "dependencies": {
    "check-more-types": "2.24.0",
    "debug": "3.2.7",
    "lazy-ass": "1.6.0",
    "lodash": "4.17.20",
    "minimist": "1.2.5",
    "q": "2.0.3",
    "quote": "0.4.0",
    "semver": "5.7.1"
  },
  "devDependencies": {
    "execa-wrap": "1.4.0",
    "git-issues": "1.3.1",
    "grunt": "0.4.5",
    "grunt-nice-package": "0.10.4",
    "jest": "22.4.4",
    "jshint-summary": "0.4.0",
    "pre-git": "3.17.1",
    "semantic-release": "15.14.0",
    "simple-commit-message": "4.1.1",
    "standard": "11.0.1"
  },
  "engines": {
    "node": ">= 0.8.0"
  },
  "homepage": "https://github.com/bahmutov/deps-ok",
  "keywords": [
    "npm",
    "install",
    "dependencies",
    "package",
    "version"
  ],
  "license": "MIT",
  "main": "index.js",
  "preferGlobal": true,
  "readmeFilename": "README.md",
  "repository": {
    "type": "git",
    "url": "https://github.com/bahmutov/deps-ok.git"
  },
  "files": [
    "index.js",
    "src",
    "bin",
    "!src/test",
    "!src/__tests__"
  ],
  "scripts": {
    "test": "npm run itself && npm run unit && npm run e2e",
    "itself": "node index.js",
    "unit": "jest src/__tests__",
    "e2e": "jest 'test/e2e.test.js'",
    "commit": "git-issues && commit-wizard",
    "issues": "git-issues",
    "size": "t=\"$(npm pack .)\"; wc -c \"${t}\"; tar tvf \"${t}\"; rm \"${t}\";",
    "semantic-release": "semantic-release",
    "lint": "standard --verbose --fix 'bin/*.js' 'src/**/*.js' 'test/*.js'",
    "pretest": "npm run lint"
  },
  "config": {
    "pre-git": {
      "commit-msg": "simple",
      "pre-commit": [
        "npm test"
      ],
      "pre-push": [
        "npm run size"
      ],
      "post-commit": [],
      "post-merge": []
    }
  },
  "release": {
    "analyzeCommits": {
      "preset": "angular",
      "releaseRules": [
        {
          "type": "break",
          "release": "major"
        }
      ]
    }
  }
}

